CREATE OR REPLACE FUNCTION public.validate_license_sale() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE d pricing_packages; m text; BEGIN IF NEW.partner_id IS DISTINCT FROM (SELECT partner_id FROM tenants WHERE id=NEW.tenant_id) THEN RAISE EXCEPTION 'Partnerzuordnung ungültig'; END IF; IF NEW.partner_id IS NOT NULL AND EXISTS(SELECT 1 FROM partners WHERE id=NEW.partner_id AND billing_mode='commission') THEN RAISE EXCEPTION 'Provisionspartner bleiben im bisherigen Abrechnungsmodell'; END IF; IF NEW.product_kind='package' THEN SELECT * INTO d FROM pricing_packages WHERE code=NEW.product_code; IF d.requires_package IS NOT NULL AND NOT EXISTS(SELECT 1 FROM license_sales WHERE tenant_id=NEW.tenant_id AND product_kind='package' AND product_code=d.requires_package AND ended_on IS NULL) AND NOT EXISTS(SELECT 1 FROM tenant_package_bookings WHERE tenant_id=NEW.tenant_id AND package_code=d.requires_package AND cancelled_at IS NULL) THEN RAISE EXCEPTION 'Benötigtes Paket fehlt'; END IF; IF d.requires_any_other AND NOT EXISTS(SELECT 1 FROM license_sales WHERE tenant_id=NEW.tenant_id AND product_kind='package' AND ended_on IS NULL) AND NOT EXISTS(SELECT 1 FROM tenant_package_bookings WHERE tenant_id=NEW.tenant_id AND cancelled_at IS NULL) THEN RAISE EXCEPTION 'Weiteres Paket fehlt'; END IF; IF EXISTS(SELECT 1 FROM license_sales s JOIN pricing_package_modules pm ON pm.module_code=s.product_code WHERE s.tenant_id=NEW.tenant_id AND s.product_kind='module' AND s.ended_on IS NULL AND pm.package_code=NEW.product_code) THEN RAISE EXCEPTION 'Paket enthält bereits einzeln verkaufte Module'; END IF; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS validate_license_sale ON public.license_sales;
CREATE TRIGGER validate_license_sale BEFORE INSERT ON public.license_sales FOR EACH ROW EXECUTE FUNCTION public.validate_license_sale();
CREATE OR REPLACE FUNCTION public.stop_dependent_license_sale() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.product_kind='package' AND NEW.ended_on IS NOT NULL AND OLD.ended_on IS NULL AND EXISTS(SELECT 1 FROM license_sales s JOIN pricing_packages p ON p.code=s.product_code WHERE s.tenant_id=OLD.tenant_id AND s.product_kind='package' AND s.ended_on IS NULL AND s.id<>OLD.id AND p.requires_package=OLD.product_code) THEN RAISE EXCEPTION 'Abhängiges Paket zuerst beenden'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS stop_dependent_license_sale ON public.license_sales;
CREATE TRIGGER stop_dependent_license_sale BEFORE UPDATE ON public.license_sales FOR EACH ROW EXECUTE FUNCTION public.stop_dependent_license_sale();
CREATE OR REPLACE FUNCTION public.install_license_billing_schedule() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM pg_extension WHERE extname='pg_cron') THEN PERFORM cron.schedule('generate-due-license-invoices','15 2 * * *','SELECT public.generate_due_license_invoices();'); END IF; END $$;
REVOKE ALL ON FUNCTION public.install_license_billing_schedule() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.install_license_billing_schedule() TO service_role;
SELECT public.install_license_billing_schedule();